CREATE PROCEDURE "informix".sp_cred_insertaproductos(pUsuario CHAR(8), pIdFuncion CHAR(10), pFamilia CHAR(3), pNum_Producto CHAR(4), pNomb_Producto CHAR(40), psub_producto INTEGER)
		RETURNING CHAR(5) AS codret; 
		
	DEFINE cCodRet 		CHAR(5);
	DEFINE iSqlErr 		INTEGER;
	DEFINE cCodRetSp 	CHAR(5);
	DEFINE iCodRetSp 	INTEGER;
	DEFINE cEmpresa     CHAR(3);
    
	
	LET cCodRet 		= '00000';
	LET iSqlErr 		= 0;
	LET cCodRetSp 		= '';
	LET iCodRetSp 		= 0;
	LET cEmpresa 		= '001';  	
	
	
	BEGIN
	
		ON EXCEPTION SET iSqlErr
			LET cCodRet = iSqlErr;
			RETURN cCodRet;
		END EXCEPTION;
		
		--SET DEBUG FILE TO '/tmp/sp_cred_insertaproductos_2021.out';
		--TRACE ON;
		
		IF pUsuario = '' OR pIdFuncion = '' OR pFamilia = '' OR pNum_Producto = ''  OR pNomb_Producto = '' THEN
			LET cCodRet = '00003';
			RETURN cCodRet;
		END IF;
		
		-- VALIDACION DE ACCESO A LA FUNCIONALIDAD
		EXECUTE PROCEDURE bdinteg:"informix".sp_cnsif_confirmaejecutivo(pUsuario, pIdFuncion) INTO cCodRet;
		IF cCodRet <> '00000' THEN
			RETURN cCodRet;
		END IF;
		
		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;
		
		EXECUTE PROCEDURE bdicred:"informix".sp_inserta_productos(cEmpresa, pUsuario, pFamilia, pNum_Producto, pNomb_Producto, psub_producto)
		INTO cCodRetSp;
		
			
		LET iCodRetSp = cCodRetSp::INTEGER;
			IF iCodRetSp < 0 THEN
				RAISE EXCEPTION iCodRetSp, 0, "ERROR EN LA EJECUCION DEL SP sp_inserta_productos";
		ELIF iCodRetSp = 1 THEN
			LET cCodRet = '00003';
			RETURN cCodRet;
		ELIF iCodRetSp = 2 THEN
			LET cCodRet = '00017';
			RETURN cCodRet;
		END IF;
			
		RETURN cCodRet;
			
	END;
	
END PROCEDURE
DOCUMENT 'AUTOR: Johnattan Esquivel Sanchez',
'FECHA: 27/08/2020',
'MODULO: CREDITO',
'FUNCIONALIDAD: Taller de Productos',
'DESCRIPCION: SPL encargado de insertar los productos',
'BD: bdicnweb';

CREATE PROCEDURE "informix".sp_ajuste_creditos(p_Empresa  CHAR(3),pfecha DATE)
   RETURNING CHAR(5);
   
---- pfecha es la fecha origen, que se tomara de la historica

   -- **************************************************************************
   -- *                      DEFINICION DE VARIABLES                           *
   -- **************************************************************************


	DEFINE CodRet   			CHAR(5);  
	DEFINE sql_err 				SMALLINT; 
	DEFINE isam_err 			SMALLINT;
	DEFINE rLog					SMALLINT;
	DEFINE error_info 			CHAR(40);  
	
	DEFINE statusCred 			CHAR(2);
	DEFINE p_NumCredito			CHAR(20);
	DEFINE vcap_insoluto		DECIMAL(14,2);
	DEFINE monto_pagos 			DECIMAL(14,2);
	DEFINE monto_pagosdia		DECIMAL(14,2);
	DEFINE v_monto_financiado	DECIMAL(14,2);
	DEFINE nvo_monto_finan 		DECIMAL(14,2);
	DEFINE vsdo_cap_insoluto 	DECIMAL(14,2);
	DEFINE suma_amortiza 		DECIMAL(14,2);
	DEFINE vfecha_cuota			DATE;
	DEFINE capdebe 				DECIMAL(14,2);
	DEFINE cappag 				DECIMAL(14,2);
	DEFINE vcapital_status		INT;


   -- **************************************************************************
   -- *                      CONTROL DE ERRORES                                *
   -- ********************  ******************************************************
	ON EXCEPTION SET sql_err, isam_err, error_info
	  LET CodRet = sql_err;
	  RETURN CodRet;
	END EXCEPTION WITH RESUME;

	-- **************************************************************************
	-- *                      ASIGNACION DE VARIABLES                           *
	-- **************************************************************************
  
	SET ISOLATION TO DIRTY READ;
	SET LOCK MODE TO WAIT 3;
	
